    // Authentication Logic
    updateBadges() {
        try {
            const visible = (typeof this.getVisibleSamples === 'function') ? this.getVisibleSamples() : (this.samples || []);
            const counts = {
                'record-notification-badge': (this.unreadRecordsCount > 0) ? this.unreadRecordsCount : 0,
                'verify-notification-badge': visible.filter(s => s.status === 'registered').length,
                'analysis-notification-badge': visible.filter(s => s.status === 'accepted').length,
                'certify-notification-badge': visible.filter(s => s.status === 'analyzing' || s.status === 'summarized' || s.status === 'analyst_signed').length,
                'followup-notification-badge': (typeof window.getPendingFollowupCount === 'function') ? window.getPendingFollowupCount() : 0,
                'user-approval-badge': (this.users || []).filter(u => u.status === 'pending').length
            };

            for (const [id, count] of Object.entries(counts)) {
                const badge = document.getElementById(id);
                if (badge) {
                    if (count > 0) {
                        badge.innerText = count;
                        badge.classList.remove('hidden');
                        badge.style.display = 'inline-block';
                    } else {
                        badge.classList.add('hidden');
                        badge.style.display = 'none';
                    }
                }
            }
        } catch (err) {
            console.error('Error in updateBadges:', err);
        }
    },

    updateAuthUI() {
        const authButtons = document.getElementById('navAuthButtons');
        const userStatusCard = document.getElementById('userStatusCard');
        
        const role = this.currentUser ? this.currentUser.role : '';
        const canAccessLab = Boolean(this.currentUser && ['lab', 'admin', 'certifier'].includes(role));
        const canAccessCertify = Boolean(this.currentUser && ['lab', 'admin', 'certifier'].includes(role));
        const isAdmin = Boolean(this.currentUser && (role === 'admin' || this.currentUser.username === 'admin'));
        const isExecutive = Boolean(this.currentUser && role === 'executive');

        if (typeof document !== 'undefined' && document.body) {
            document.body.classList.toggle('role-admin', isAdmin);
        }

        if (this.currentUser) {
            authButtons.innerHTML = `<button class="btn btn-secondary" onclick="app.logout()"><i class="fa-solid fa-arrow-right-from-bracket"></i> ออกจากระบบ</button>`;
            userStatusCard.innerHTML = `
                <div class="user-status-name"><i class="fa-solid fa-circle-user"></i> ${this.currentUser.fullname}</div>
                <div class="user-status-role">${role === 'admin' ? 'ผู้ดูแลระบบ (Admin)' : role === 'executive' ? 'ผู้บริหาร' : role === 'lab' ? 'เจ้าหน้าที่ห้องปฏิบัติการ' : role === 'certifier' ? 'ผู้รับรองรายงาน' : 'ผู้เก็บตัวอย่าง'}</div>
            `;
        } else {
            authButtons.innerHTML = `<button class="btn btn-primary" onclick="app.showLoginModal()"><i class="fa-solid fa-user-lock"></i> เข้าสู่ระบบ</button>`;
            userStatusCard.innerHTML = `<div class="user-status-name">ผู้เยี่ยมชมระบบ</div><div class="user-status-role">ยังไม่ได้เข้าสู่ระบบ</div>`;
        }

        // Show/hide sample collection menu for executive (executive is strategic read-only)
        const sampleRecordMenu = document.getElementById('menu-sample-record');
        if (sampleRecordMenu) {
            sampleRecordMenu.style.setProperty('display', isExecutive ? 'none' : 'flex', 'important');
            sampleRecordMenu.classList.toggle('role-hidden', isExecutive);
        }

        // Show/hide lab menus based on role (strictly hidden for collectors, hospitals, ssj, executives, and general visitors)
        // Certifier has the exact same visibility as lab
        document.querySelectorAll('#menu-lab-verify, #menu-lab-analysis, #menu-lab-certify').forEach(el => {
            el.style.setProperty('display', canAccessLab ? 'flex' : 'none', 'important');
            el.classList.toggle('role-hidden', !canAccessLab);
        });
        
        const adminMenu = document.getElementById('menu-manage-users');
        if (adminMenu) {
            adminMenu.style.setProperty('display', isAdmin ? 'flex' : 'none', 'important');
            adminMenu.classList.toggle('role-hidden', !isAdmin);
        }

        // Enforce role-based visibility for Provincial Email Dispatch and Edit Approval buttons
        this.updateProvEmailButtonVisibility();
        this.updateEditApprovalButtonVisibility();

        // Enforce hiding of follow-up action button on dashboard for admin and executive
        const btnManageAction = document.querySelector('.btn-manage-actions');
        if (btnManageAction) {
            if (isAdmin || isExecutive) {
                btnManageAction.style.setProperty('display', 'none', 'important');
            } else if (!btnManageAction.style.display || btnManageAction.style.display === 'none') {
                if (typeof window.updateCorrectiveActionGovernance === 'function' && window.currentCachedSamples) {
                    window.updateCorrectiveActionGovernance(window.currentCachedSamples);
                }
            }
        }
        
        // Re-evaluate current view: ensure unauthorized users are redirected to dashboard
        const activeView = document.querySelector('.content-view.active');
        if (activeView) {
            const currentViewName = activeView.id.replace('view-', '');
            if ((currentViewName === 'lab-verify' || currentViewName === 'lab-analysis') && !canAccessLab) {
                this.switchView('dashboard');
            } else if (currentViewName === 'lab-certify' && !canAccessCertify) {
                this.switchView('dashboard');
            } else if (currentViewName === 'manage-users' && !isAdmin) {
                this.switchView('dashboard');
            } else if (currentViewName === 'sample-record' && isExecutive) {
                this.switchView('dashboard');
            }
        }
    },

    updateProvEmailButtonVisibility() {
        const canSendProvEmail = Boolean(
            this.currentUser && ['admin', 'lab', 'certifier'].includes(this.currentUser.role)
        );
        document.querySelectorAll('.btn-prov-email-dispatch').forEach(btn => {
            btn.style.setProperty('display', canSendProvEmail ? 'inline-flex' : 'none', 'important');
        });
    },

    updateEditApprovalButtonVisibility() {
        const canEditApproval = Boolean(
            this.currentUser && ['admin', 'lab', 'certifier'].includes(this.currentUser.role)
        );
        const btn = document.getElementById('btnEditApproval');
        if (btn) {
            btn.style.setProperty('display', canEditApproval ? 'inline-flex' : 'none', 'important');
        }
    },

